package com.testora.service;
import com.testora.dao.ProblemDAO; import com.testora.model.*; import java.util.*; import java.util.stream.*;
/** Business operations for browsing and maintaining problems. */
public class ProblemService {private final ProblemDAO dao=new ProblemDAO(); public List<Problem> browse(String difficulty,String query){try{return dao.findAll().stream().filter(p->difficulty==null||difficulty.isBlank()||p.getDifficulty().equalsIgnoreCase(difficulty)).filter(p->query==null||p.getTitle().toLowerCase().contains(query.toLowerCase())).sorted().toList();}catch(Exception e){throw new IllegalStateException(e.getMessage(),e);}}
 public Optional<Problem> find(long id){try{return dao.findById(id);}catch(Exception e){return Optional.empty();}} public List<TestCase> tests(long id,boolean all){try{return dao.testCases(id,all);}catch(Exception e){return List.of();}} public List<Topic> topics(){try{return dao.topics();}catch(Exception e){return List.of();}} public Problem save(Problem p,List<TestCase> tests)throws Exception{if(p.getId()==0)dao.create(p);else dao.update(p);dao.replaceTests(p.getId(),tests);return p;} public boolean delete(long id)throws Exception{return dao.delete(id);} }
